contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        (uint preBalance,) = c.Acc(address(this));

        c.Put{value: putAmount}(lockTime);

        (uint postPutBalance,) = c.Acc(address(this));

        // Check the Getter grew by exactly putAmount
        assert(postPutBalance == preBalance + putAmount);

        uint cBalAfterPut = address(c).balance;
        assert(cBalAfterPut == cBalBefore + putAmount);

        // Try to collect some amount. It may fail if MinSum is too high or lockTime not passed.
        uint sendBefore = address(this).balance;
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        (uint postCollectBalance,) = c.Acc(address(this));

        if (success) {
            // Contract should have transferred exactly collectAmount to this test
            assert(address(this).balance == sendBefore + collectAmount);
            assert(postCollectBalance == postPutBalance - collectAmount);
            assert(address(c).balance == cBalAfterPut - collectAmount);
        } else {
            // Nothing changed on failure
            assert(address(this).balance == sendBefore);
            assert(postCollectBalance == postPutBalance);
            assert(address(c).balance == cBalAfterPut);
        }

        // General invariant: contract balance equals initial + put - (success ? collect : 0)
        assert(address(c).balance == cBalBefore + putAmount - (success ? collectAmount : 0));
    }

    receive() external payable {}
}

